import{_ as r,c as i,o as t,a2 as o}from"./chunks/framework.CIiVzG-O.js";const m=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/introduction.md","filePath":"fr/guide/introduction.md","lastUpdated":1793163976000}'),a={name:"fr/guide/introduction.md"};function s(n,e,l,c,u,p){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><h2 id="a-propos-de-nuezip" tabindex="-1">À propos de NueZip <a class="header-anchor" href="#a-propos-de-nuezip" aria-label="Permalink to &quot;À propos de NueZip&quot;">​</a></h2><p>NueZip est un gestionnaire d&#39;archives professionnel pour macOS, conçu pour la rapidité, la fiabilité et la facilité d&#39;utilisation. Que vous ayez besoin de compresser des fichiers, d&#39;extraire des archives, de convertir des formats ou de gérer des archives protégées par mot de passe, NueZip prend tout en charge avec une expérience native macOS.</p><p>Développé avec Swift 6 et SwiftUI, NueZip tire pleinement parti d&#39;Apple Silicon et des technologies macOS pour offrir un outil de gestion d&#39;archives rapide, léger et sécurisé.</p><h2 id="fonctionnalites-cles" tabindex="-1">Fonctionnalités clés <a class="header-anchor" href="#fonctionnalites-cles" aria-label="Permalink to &quot;Fonctionnalités clés&quot;">​</a></h2><h3 id="📦-prise-en-charge-multi-formats" tabindex="-1">📦 <strong>Prise en charge multi-formats</strong> <a class="header-anchor" href="#📦-prise-en-charge-multi-formats" aria-label="Permalink to &quot;📦 **Prise en charge multi-formats**&quot;">​</a></h3><p>NueZip prend en charge tous les principaux formats d&#39;archives :</p><ul><li><strong>RAR</strong> — Lecture seule avec prise en charge multi-volumes</li><li><strong>ZIP</strong> — Compression universelle avec chiffrement AES</li><li><strong>7-Zip</strong> — Taux de compression élevé avec LZMA2</li><li><strong>TAR</strong> — Regroupement d&#39;archives avec GZIP/BZIP2 optionnel</li><li><strong>GZIP / BZIP2</strong> — Formats de compression autonomes</li></ul><h3 id="⚡-extraction-rapide" tabindex="-1">⚡ <strong>Extraction rapide</strong> <a class="header-anchor" href="#⚡-extraction-rapide" aria-label="Permalink to &quot;⚡ **Extraction rapide**&quot;">​</a></h3><p>L&#39;architecture à double moteur sélectionne le moteur optimal pour chaque format, garantissant les vitesses d&#39;extraction les plus rapides possibles.</p><h3 id="🔐-protection-par-mot-de-passe-et-chiffrement" tabindex="-1">🔐 <strong>Protection par mot de passe et chiffrement</strong> <a class="header-anchor" href="#🔐-protection-par-mot-de-passe-et-chiffrement" aria-label="Permalink to &quot;🔐 **Protection par mot de passe et chiffrement**&quot;">​</a></h3><p>Créez des archives protégées par mot de passe avec un chiffrement conforme aux normes de l&#39;industrie. Le gestionnaire de mots de passe intégré stocke les identifiants en toute sécurité dans votre trousseau local.</p><h3 id="📋-operations-par-lot" tabindex="-1">📋 <strong>Opérations par lot</strong> <a class="header-anchor" href="#📋-operations-par-lot" aria-label="Permalink to &quot;📋 **Opérations par lot**&quot;">​</a></h3><p>Traitez plusieurs fichiers à la fois :</p><ul><li><strong>Compression par lot</strong> — Compressez plusieurs éléments en archives individuelles</li><li><strong>Extraction par lot</strong> — Extrayez plusieurs archives simultanément</li><li><strong>Conversion par lot</strong> — Convertissez des archives entre formats en masse</li><li><strong>Chiffrement par lot</strong> — Appliquez une protection par mot de passe à plusieurs archives</li></ul><h3 id="🛠️-outils-avances" tabindex="-1">🛠️ <strong>Outils avancés</strong> <a class="header-anchor" href="#🛠️-outils-avances" aria-label="Permalink to &quot;🛠️ **Outils avancés**&quot;">​</a></h3><ul><li><strong>Réparation d&#39;archive</strong> — Réparez les archives RAR et ZIP corrompues</li><li><strong>Conversion de format</strong> — Convertissez entre n&#39;importe quels formats pris en charge</li><li><strong>Test de performance</strong> — Testez la vitesse et l&#39;évaluation de compression</li><li><strong>Recherche d&#39;archive</strong> — Recherchez des fichiers dans les archives par nom</li><li><strong>Visionneuse d&#39;informations sur les fichiers</strong> — Affichez les métadonnées détaillées des entrées d&#39;archive</li><li><strong>Prise en charge des volumes/fractionnement</strong> — Créez des archives multi-volumes</li></ul><h3 id="🖥️-experience-macos-native" tabindex="-1">🖥️ <strong>Expérience macOS native</strong> <a class="header-anchor" href="#🖥️-experience-macos-native" aria-label="Permalink to &quot;🖥️ **Expérience macOS native**&quot;">​</a></h3><ul><li><strong>Swift 6 + SwiftUI</strong> — Interface moderne et réactive</li><li><strong>Native Apple Silicon</strong> — Optimisé pour les puces de série M</li><li><strong>Intégration Finder</strong> — Extension de menu contextuel au clic droit</li><li><strong>Glisser-déposer</strong> — Accès rapide via le panneau de dépôt de la barre de menu</li><li><strong>Utilisation minimale des ressources</strong> — Fonctionnement léger en arrière-plan</li></ul><h2 id="configuration-requise" tabindex="-1">Configuration requise <a class="header-anchor" href="#configuration-requise" aria-label="Permalink to &quot;Configuration requise&quot;">​</a></h2><ul><li><strong>Système d&#39;exploitation</strong> : macOS 14 Sonoma ou ultérieur</li><li><strong>Processeur</strong> : Apple Silicon (série M) ou Intel (64 bits)</li><li><strong>Mémoire</strong> : 4 Go de RAM minimum, 8 Go recommandé</li><li><strong>Stockage</strong> : ~50 Mo pour l&#39;installation</li></ul><h2 id="langues-prises-en-charge" tabindex="-1">Langues prises en charge <a class="header-anchor" href="#langues-prises-en-charge" aria-label="Permalink to &quot;Langues prises en charge&quot;">​</a></h2><p>NueZip prend en charge l&#39;anglais, le chinois (simplifié), le chinois (traditionnel), le japonais, le coréen et de nombreuses autres langues.</p><h2 id="pour-commencer" tabindex="-1">Pour commencer <a class="header-anchor" href="#pour-commencer" aria-label="Permalink to &quot;Pour commencer&quot;">​</a></h2><p>Si vous découvrez NueZip, commencez par le <a href="/fr/guide/installation.html">Guide d&#39;installation</a> pour faire fonctionner l&#39;application sur votre Mac.</p>',25)])])}const h=r(a,[["render",s]]);export{m as __pageData,h as default};
